        public static SourceSphereModifiers Get(SphereId type, int level, string branch, string final)
        {
            level = Math.Max(0, Math.Min(7, level));
            var index = final == branch + "_final_1" ? 0 : final == branch + "_final_2" ? 1 : final == branch + "_final_3" ? 2 : -1;
            var key = type.ToString().ToLowerInvariant() + "|" + level + "|" + (branch ?? "") + "|" + index;
            if (!Values.TryGetValue(key, out var value)) value = Values[type.ToString().ToLowerInvariant() + "|" + level + "||-1"];
            return value.Clone();
        }
